head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Item);
        await scwin.setHeader();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        scwin.detail(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41101.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Uly_OnLoadError
 * @description dts_Uly 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Uly_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Uly);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.dts_Uly_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_CheckDouble_OnLoadError
 * @description dts_CheckDouble 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CheckDouble_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_CheckDouble);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.dts_CheckDouble_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt.setValue("총 " + dts_List.getRowCount() + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41101.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lce.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41101.btn_Save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ELWUnderlyingAsset.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkDouble
 * @description check Double 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDouble = async function() {
    url += "&WRNT_ULY_NM=" + txb_WRNT_ULY_NM.getValue();
    url += "&WRNT_ULY_ENG_NM=" + txb_WRNT_ULY_ENG_NM.getValue();
    const sbmOptions = {
        id : "sbm_dts_CheckDouble",
        action : "/ELWUnderlyingAsset.do",
        ref : "",
        target : "dts_CheckDouble=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Uly",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Uly=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Uly.insertRow();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let TR_JOB;
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lce.fn_isProcess(TR_JOB)) return;
        dts_Uly.setCellData(1, "WRNT_ULY_NM", txb_WRNT_ULY_NM.getValue());
        dts_Uly.setCellData(1, "WRNT_ULY_ENG_NM", txb_WRNT_ULY_ENG_NM.getValue());

        // alert('[dts_Uly]'+dts_Uly.text);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ELWUnderlyingAsset.do",
            ref : "dts_Uly",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.detail = function(row) {
    dts_Uly.setCellData(1, "ISUR_CD", dts_List.getCellData(row, "ISUR_CD"));
    dts_Uly.setCellData(1, "COM_NM", dts_List.getCellData(row, "COM_NM"));
    dts_Uly.setCellData(1, "COM_ENG_NM", dts_List.getCellData(row, "COM_ENG_NM"));
    dts_Uly.setCellData(1, "IDX_TP_NM", dts_List.getCellData(row, "IDX_TP_NM"));
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_NM, "한글기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_NM, 8, "한글기초자산명")) return false;
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_ENG_NM, "영문기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_ENG_NM, 8, "영문기초자산명")) return false;
    await scwin.checkDouble();
    if (dts_CheckDouble.getRowCount() > 0) {
        await $c.win.alert("이미 동일한 약명이 있습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    return true;
};
